with enriched as (select *, first_value(amount) ignore nulls over (partition by store_id order by shipping_fee, id rows between unbounded preceding and current row) as first_known_amount, sum(discount) over (partition by store_id, customer_id order by discount, id rows between unbounded preceding and current row) as cumulative_discount from orders) select s.id, s.customer_id, s.store_id, s.order_date, s.status, s.channel, s.amount, s.discount, s.shipping_fee, case when channel rlike '^(web|store)$' then 'GROUP_B' else 'CORE' end as channel_zone, (select min(t2.balance) from accounts t2 where t2.customer_id = s.customer_id) as min_account_balance from enriched s;
